input.script:
companies = list_companies({})
first = list_contacts({ page: 1 })
remaining = for page in list.range(2, first.total_pages + 1) {
    result = list_contacts({ page })
    return result.items
}
contacts = fold acc = first.items for page in remaining {
    return acc + page
}
domain_to_company = fold acc = {} for c in companies {
    return acc + { [c.domain]: c.name }
}

is_e164 = fun(phone) {
    return regex.test(phone, "^\\+1\\d{10}$")
}

to_e164 = fun(phone) {
    digits = regex.replace(phone, "[^0-9]", "")
    normalized = if text.starts_with(digits, "1") and text.length(digits) == 11 {
        return digits
    } else if text.length(digits) == 10 {
        return "1" + digits
    } else {
        return digits
    }
    return "+" + normalized
}

results = for contact in contacts {
    phone = contact.phone if contact.phone != null else ""
    need_phone = phone != "" and not regex.test(phone, "^\\+1\\d{10}$")
    new_phone = to_e164(phone) if need_phone else null

    email = contact.email if contact.email != null else ""
    company_empty = contact.company == null or contact.company == ""
    domain = null
    domain_parts = text.split(email, "@")
    domain = domain_parts[1] if list.length(domain_parts) == 2 else null
    new_company = domain_to_company[domain] if company_empty and domain != null and domain in domain_to_company else null

    updated = false
    if need_phone or new_company != null {
        u = update_contact({
            id: contact.id,
            phone: new_phone if need_phone else null,
            company: new_company if new_company != null else null
        })
        updated = true
    }

    return {
        phone_fixed: need_phone,
        company_filled: new_company != null
    }
}

phones_fixed = fold acc = 0 for r in results {
    return acc + (1 if r.phone_fixed else 0)
}
companies_filled = fold acc = 0 for r in results {
    return acc + (1 if r.company_filled else 0)
}

submit = submit_result({ answer: { phones_fixed: phones_fixed, companies_filled: companies_filled } })
return { phones_fixed, companies_filled, submit }
